CREATE TABLE inquiries(id INT AUTO_INCREMENT PRIMARY KEY,type ENUM('contact','quote') NOT NULL,name VARCHAR(120),business VARCHAR(160),email VARCHAR(160),phone VARCHAR(40),service VARCHAR(120),budget VARCHAR(80),timeline VARCHAR(80),message TEXT,status VARCHAR(30) DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applications(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),email VARCHAR(160),phone VARCHAR(40),position VARCHAR(160),experience VARCHAR(60),education VARCHAR(200),linkedin VARCHAR(255),portfolio VARCHAR(255),github VARCHAR(255),cv_file VARCHAR(80),cover_letter TEXT,status VARCHAR(30) DEFAULT 'received',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY dup(email,position));
CREATE TABLE rate_limits(ip VARCHAR(45),route VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY(ip,route,created_at));
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(160) UNIQUE,password_hash VARCHAR(255),role VARCHAR(20) DEFAULT 'admin');
CREATE TABLE IF NOT EXISTS submissions(id INT AUTO_INCREMENT PRIMARY KEY,type VARCHAR(20),data TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
